parameters.jsCode:
// Collapse the Applications tab into one item: the links already saved, the next serial
// number and the row count. Two reasons this exists as its own node:
//  1. Read Applications emits one item per row; without collapsing, every source
//     branch downstream would fire once per existing row.
//  2. Raw links are passed on untouched. URL normalisation happens in one
//     place only (Filter, Rank & Cap) so the sheet side and the new-job side
//     can never drift apart and silently break dedupe.
//
// Read Applications has "Always Output Data" on, so an empty sheet arrives here as
// a single {} item rather than stopping the workflow.

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);

// Header lookup is case-insensitive so a "Job Posting Link" header still
// dedupes - but the append side needs exact lowercase headers anyway.
const pick = (row, name) => {
  const key = Object.keys(row).find(k => k.trim().toLowerCase() === name);
  return key === undefined ? undefined : row[key];
};

const links = [];
let maxSno = 0;
for (const row of rows) {
  const link = pick(row, 'job posting link');
  if (link) links.push(String(link));
  const n = parseInt(pick(row, 's.no'), 10);
  if (!isNaN(n) && n > maxSno) maxSno = n;
}

console.log(`[sheet] ${rows.length} existing rows | ${links.length} links | next s.no ${maxSno + 1}`);

return [{ json: { existing_links: links, existing_row_count: rows.length, next_sno: maxSno + 1 } }];

// Fan out one item per Greenhouse board so the HTTP node makes one request
// per company. If the list is empty this returns nothing; "Always Output
// Data" then sends a single empty item, the request 404s harmlessly, and Map
// Greenhouse reports the family as disabled. That keeps every Merge input
// fed, so the Merge never waits on a branch that didn't run.
const boards = $('Set Job Search Criteria').first().json.greenhouse_boards ?? [];
console.log(`[greenhouse] requesting ${boards.length} boards`);
return boards.map(b => ({ json: { company: b.company, token: b.token } }));

// Greenhouse -> unified job shape. Pure field mapping: HTML stripping and
// date normalisation happen once, in Normalize Jobs, for every source alike.
//
// Each response is tied back to its company through paired items
// (itemMatching) rather than array position, so a failed request can't shift
// every later company onto the wrong jobs.
const SOURCE = 'Greenhouse';
const configured = $('Set Job Search Criteria').first().json.greenhouse_boards ?? [];

if (!configured.length) {
  console.log(`[${SOURCE}] disabled (empty board list)`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company', status: 'disabled', count: 0, boards: [] } }];
}

// Pull a short, human-readable failure reason out of an n8n error item.
const failReason = (err) => {
  const msg = typeof err === 'string' ? err : (err?.message ?? JSON.stringify(err ?? ''));
  const code = err?.httpCode ?? err?.status ?? (String(msg).match(/\b[45]\d\d\b/) ?? [])[0];
  return code ? `HTTP ${code}` : String(msg).slice(0, 60);
};

// itemMatching throws when an item has no pairing - which is the case for
// the placeholder {} that "Always Output Data" emits when every board
// came back empty. Treat that as "no target" rather than crashing.
const targetFor = (idx) => {
  try { return $('Distribute Greenhouse Boards').itemMatching(idx)?.json ?? {}; } catch { return {}; }
};

// Seeded from config so a board that got no response at all still shows as dead.
const boards = new Map(configured.map(c => [c.company, { company: c.company, status: 'dead', jobs: 0, reason: 'no response' }]));
const out = [];

$input.all().forEach((item, idx) => {
  const target = targetFor(idx);
  if (!target.company) return;                    // unpaired placeholder item
  const company = target.company;
  const res = item.json ?? {};
  const b = boards.get(company) ?? { company, status: 'dead', jobs: 0, reason: 'no response' };
  boards.set(company, b);

  if (res.error) { b.status = 'dead'; b.reason = failReason(res.error); return; }
  const jobs = Array.isArray(res.jobs) ? res.jobs : [];
  if (!jobs.length) { b.status = 'dead'; b.reason = 'empty'; return; }
  b.status = 'ok'; b.reason = '';

  for (const j of jobs) {
    b.jobs++;
    out.push({ json: {
      _kind: 'job', tier: 'company', board: SOURCE, source: `${SOURCE}: ${company}`, company,
      title: j.title ?? '',
      url: j.absolute_url ?? '',
      description_raw: j.content ?? '',          // entity-encoded HTML; decoded downstream
      posted_raw: j.first_published ?? j.updated_at ?? '',
      location: j.location?.name ?? ''
    }});
  }
});

const list = [...boards.values()];
const ok = list.filter(b => b.status === 'ok');
const dead = list.filter(b => b.status !== 'ok');
console.log(`[${SOURCE}] ${ok.length}/${list.length} boards ok, ${out.length} jobs` +
            (dead.length ? ` | dead: ${dead.map(b => `${b.company} (${b.reason})`).join(', ')}` : ''));

return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company',
                  status: ok.length ? 'ok' : 'unavailable', count: out.length, boards: list } }, ...out];

// Fan out one item per Ashby board (see Greenhouse Targets for why an empty
// list is safe).
const boards = $('Set Job Search Criteria').first().json.ashby_boards ?? [];
console.log(`[ashby] requesting ${boards.length} boards`);
return boards.map(b => ({ json: { company: b.company, board: b.board } }));

// Ashby -> unified job shape. Pure field mapping (see Map Greenhouse for the
// paired-item reasoning).
const SOURCE = 'Ashby';
const configured = $('Set Job Search Criteria').first().json.ashby_boards ?? [];

if (!configured.length) {
  console.log(`[${SOURCE}] disabled (empty board list)`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company', status: 'disabled', count: 0, boards: [] } }];
}

const failReason = (err) => {
  const msg = typeof err === 'string' ? err : (err?.message ?? JSON.stringify(err ?? ''));
  const code = err?.httpCode ?? err?.status ?? (String(msg).match(/\b[45]\d\d\b/) ?? [])[0];
  return code ? `HTTP ${code}` : String(msg).slice(0, 60);
};

// itemMatching throws when an item has no pairing - which is the case for
// the placeholder {} that "Always Output Data" emits when every board
// came back empty. Treat that as "no target" rather than crashing.
const targetFor = (idx) => {
  try { return $('Distribute Ashby Boards').itemMatching(idx)?.json ?? {}; } catch { return {}; }
};

// Seeded from config so a board that got no response at all still shows as dead.
const boards = new Map(configured.map(c => [c.company, { company: c.company, status: 'dead', jobs: 0, reason: 'no response' }]));
const out = [];

$input.all().forEach((item, idx) => {
  const target = targetFor(idx);
  if (!target.company) return;                    // unpaired placeholder item
  const company = target.company;
  const res = item.json ?? {};
  const b = boards.get(company) ?? { company, status: 'dead', jobs: 0, reason: 'no response' };
  boards.set(company, b);

  if (res.error) { b.status = 'dead'; b.reason = failReason(res.error); return; }
  // Ashby answers 200 with an empty list for unknown boards, so "empty"
  // is the only signal that a board name is wrong.
  const jobs = (Array.isArray(res.jobs) ? res.jobs : []).filter(j => j.isListed !== false);
  if (!jobs.length) { b.status = 'dead'; b.reason = 'empty'; return; }
  b.status = 'ok'; b.reason = '';

  for (const j of jobs) {
    b.jobs++;
    // Ashby lists the main office plus "secondaryLocations"; keep them all so
    // a role that's NYC-or-Remote-US isn't judged on NYC alone.
    const extra = (j.secondaryLocations ?? []).map(l => l?.location ?? l).filter(Boolean);
    const locs = [j.location, ...extra].filter(Boolean);
    if (j.isRemote && !locs.some(l => /remote/i.test(l))) locs.push('Remote');
    out.push({ json: {
      _kind: 'job', tier: 'company', board: SOURCE, source: `${SOURCE}: ${company}`, company,
      title: j.title ?? '',
      url: j.jobUrl ?? j.applyUrl ?? '',
      description_raw: j.descriptionPlain || j.descriptionHtml || '',
      posted_raw: j.publishedAt ?? '',
      location: locs.join(' | ')
    }});
  }
});

const list = [...boards.values()];
const ok = list.filter(b => b.status === 'ok');
const dead = list.filter(b => b.status !== 'ok');
console.log(`[${SOURCE}] ${ok.length}/${list.length} boards ok, ${out.length} jobs` +
            (dead.length ? ` | dead: ${dead.map(b => `${b.company} (${b.reason})`).join(', ')}` : ''));

return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company',
                  status: ok.length ? 'ok' : 'unavailable', count: out.length, boards: list } }, ...out];

// Fan out one item per Lever board (see Greenhouse Targets for why an empty
// list is safe).
const boards = $('Set Job Search Criteria').first().json.lever_boards ?? [];
console.log(`[lever] requesting ${boards.length} boards`);
return boards.map(b => ({ json: { company: b.company, slug: b.slug } }));

// Lever -> unified job shape. Lever returns a bare array, which the HTTP node
// splits into one item per posting - so a board yields many items, all paired
// back to the same Lever Targets item. A board that returns [] yields no items
// at all, which is why boards are seeded from the target list first.
const SOURCE = 'Lever';
const configured = $('Set Job Search Criteria').first().json.lever_boards ?? [];

if (!configured.length) {
  console.log(`[${SOURCE}] disabled (empty board list)`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company', status: 'disabled', count: 0, boards: [] } }];
}

const failReason = (err) => {
  const msg = typeof err === 'string' ? err : (err?.message ?? JSON.stringify(err ?? ''));
  const code = err?.httpCode ?? err?.status ?? (String(msg).match(/\b[45]\d\d\b/) ?? [])[0];
  return code ? `HTTP ${code}` : String(msg).slice(0, 60);
};

// itemMatching throws when an item has no pairing - which is the case for
// the placeholder {} that "Always Output Data" emits when every board
// came back empty. Treat that as "no target" rather than crashing.
const targetFor = (idx) => {
  try { return $('Distribute Lever Boards').itemMatching(idx)?.json ?? {}; } catch { return {}; }
};

const boards = new Map(configured.map(c => [c.company, { company: c.company, status: 'dead', jobs: 0, reason: 'empty' }]));
const out = [];

$input.all().forEach((item, idx) => {
  const target = targetFor(idx);
  if (!target.company) return;                    // unpaired placeholder item
  const company = target.company;
  const j = item.json ?? {};
  const b = boards.get(company) ?? { company, status: 'dead', jobs: 0, reason: 'empty' };
  boards.set(company, b);

  if (j.error) { if (!b.jobs) { b.status = 'dead'; b.reason = failReason(j.error); } return; }
  if (!j.text || !j.hostedUrl) return;

  b.status = 'ok'; b.reason = ''; b.jobs++;
  // The plain description omits the requirement lists, which is where most
  // of the substance is - append them so the description check is fair.
  const lists = (j.lists ?? []).map(l => `${l.text ?? ''}: ${l.content ?? ''}`).join(' ');
  const locs = j.categories?.allLocations?.length ? j.categories.allLocations : [j.categories?.location].filter(Boolean);
  if (j.workplaceType === 'remote' && !locs.some(l => /remote/i.test(l))) locs.push('Remote');
  out.push({ json: {
    _kind: 'job', tier: 'company', board: SOURCE, source: `${SOURCE}: ${company}`, company,
    title: j.text,
    url: j.hostedUrl,
    description_raw: `${j.descriptionPlain ?? ''} ${lists} ${j.additionalPlain ?? ''}`,
    posted_raw: j.createdAt ?? '',               // unix milliseconds (as a string)
    location: locs.join(' | ')
  }});
});

const list = [...boards.values()];
const ok = list.filter(b => b.status === 'ok');
const dead = list.filter(b => b.status !== 'ok');
console.log(`[${SOURCE}] ${ok.length}/${list.length} boards ok, ${out.length} jobs` +
            (dead.length ? ` | dead: ${dead.map(b => `${b.company} (${b.reason})`).join(', ')}` : ''));

return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'company',
                  status: ok.length ? 'ok' : 'unavailable', count: out.length, boards: list } }, ...out];

// Remotive -> unified job shape. Remotive's free feed is delayed 24h and
// asks for at most 4 calls a day; every 3 days is well inside that.
const SOURCE = 'Remotive';
const res = $input.first()?.json ?? {};
const jobs = Array.isArray(res.jobs) ? res.jobs : [];

if (res.error || !jobs.length) {
  console.log(`[${SOURCE}] unavailable${res.error ? ' (request failed)' : ' (no jobs in response)'}`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'unavailable', count: 0 } }];
}

const out = jobs.map(j => ({ json: {
  _kind: 'job', tier: 'aggregate', board: SOURCE, source: SOURCE,
  company: j.company_name ?? '',
  title: j.title ?? '',
  url: j.url ?? '',                               // remotive.com link - satisfies their link-back term
  description_raw: j.description ?? '',
  posted_raw: j.publication_date ?? '',
  location: j.candidate_required_location ?? ''
}}));

console.log(`[${SOURCE}] ${out.length} jobs`);
return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'ok', count: out.length } }, ...out];

// RemoteOK -> unified job shape. The API returns a bare array that the HTTP
// node splits into items; the first element is a legal notice, not a job,
// so anything carrying a 'legal' field or lacking a position is skipped.
const SOURCE = 'RemoteOK';
const items = $input.all().map(i => i.json ?? {});
const failed = items.length === 1 && items[0].error;
const jobs = items.filter(j => !j.legal && !j.error && (j.position || j.title));

if (failed || !jobs.length) {
  console.log(`[${SOURCE}] unavailable${failed ? ' (request failed)' : ' (no jobs in response)'}`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'unavailable', count: 0 } }];
}

const out = jobs.map(j => ({ json: {
  _kind: 'job', tier: 'aggregate', board: SOURCE, source: SOURCE,
  company: j.company ?? '',
  title: j.position ?? j.title ?? '',
  url: j.url ?? j.apply_url ?? '',                // remoteok.com link - satisfies their link-back term
  description_raw: j.description ?? '',
  posted_raw: j.date ?? j.epoch ?? '',            // ISO string, with unix seconds as fallback
  location: j.location ?? ''                      // often blank; blank locations pass the filter
}}));

console.log(`[${SOURCE}] ${out.length} jobs`);
return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'ok', count: out.length } }, ...out];

// Jobicy -> unified job shape. The request already asks for geo=usa, so this
// board is pre-filtered server-side; the location rules still run on it.
const SOURCE = 'Jobicy';
const res = $input.first()?.json ?? {};
const jobs = Array.isArray(res.jobs) ? res.jobs : [];

if (res.error || !jobs.length) {
  console.log(`[${SOURCE}] unavailable${res.error ? ' (request failed)' : ' (no jobs in response)'}`);
  return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'unavailable', count: 0 } }];
}

const out = jobs.map(j => ({ json: {
  _kind: 'job', tier: 'aggregate', board: SOURCE, source: SOURCE,
  company: j.companyName ?? '',
  title: j.jobTitle ?? '',
  url: j.url ?? '',                               // jobicy.com link - satisfies their credit term
  description_raw: j.jobDescription || j.jobExcerpt || '',
  posted_raw: j.pubDate ?? '',
  location: j.jobGeo ?? ''
}}));

console.log(`[${SOURCE}] ${out.length} jobs`);
return [{ json: { _kind: 'source_status', source: SOURCE, tier: 'aggregate', status: 'ok', count: out.length } }, ...out];

// Six sources, six shapes, one schema. The Map nodes only rename fields;
// this node does the cleaning that has to be identical for every source:
//  - descriptions: decode entities and strip HTML. Greenhouse double-encodes
//    (&lt;p&gt; inside JSON), so decode -> strip -> decode -> strip.
//  - dates: ISO strings, "YYYY-MM-DD HH:mm:ss", unix seconds and unix
//    milliseconds (sometimes as strings) all become YYYY-MM-DD, or null.
//  - text fields: trimmed, whitespace collapsed.
// Source-status items pass straight through for the Run Log.

const cfg = $('Set Job Search Criteria').first().json;

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '-', mdash: '-',
                hellip: '...', lsquo: "'", rsquo: "'", ldquo: '"', rdquo: '"', bull: '•', middot: '·',
                copy: '©', reg: '®', trade: '™', eacute: 'é', egrave: 'è', uuml: 'ü', ouml: 'ö', auml: 'ä' };
const decode = (s) => String(s ?? '')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&([a-z]+);/gi, (m, name) => NAMED[name.toLowerCase()] ?? m);
const stripTags = (s) => s
  .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ');
const clean = (s) => stripTags(decode(stripTags(decode(s)))).replace(/\s+/g, ' ').trim();

const now = Date.now();
const toIsoDate = (v) => {
  if (v === null || v === undefined || v === '') return null;
  let d;
  const s = String(v).trim();
  if (/^\d{9,13}$/.test(s)) {                     // unix seconds (<1e12) or milliseconds
    const n = Number(s);
    d = new Date(n < 1e12 ? n * 1000 : n);
  } else {
    d = new Date(/^\d{4}-\d{2}-\d{2} \d/.test(s) ? s.replace(' ', 'T') : s);
  }
  if (isNaN(d.getTime())) return null;
  // Reject obvious garbage: pre-2015 epochs from bad parsing, or the future.
  if (d.getUTCFullYear() < 2015 || d.getTime() > now + 86400000) return null;
  return d.toISOString().slice(0, 10);
};

const all = $input.all().map(i => i.json);
const statuses = all.filter(r => r._kind === 'source_status');
const out = statuses.map(s => ({ json: s }));
const perSource = {};

for (const j of all) {
  if (j._kind !== 'job') continue;
  const description = clean(j.description_raw);
  out.push({ json: {
    _kind: 'job',
    tier: j.tier,
    board: j.board,
    source: j.source,
    company: String(j.company ?? '').replace(/\s+/g, ' ').trim(),
    title: clean(j.title),
    url: String(j.url ?? '').trim(),
    description,                                   // full cleaned text; trimmed for the sheet later
    posted_date: toIsoDate(j.posted_raw),
    location: clean(j.location)
  }});
  perSource[j.board] = (perSource[j.board] ?? 0) + 1;
}

console.log(`[normalize] ${out.length - statuses.length} jobs from ${statuses.length} sources | ` +
            Object.entries(perSource).map(([k, v]) => `${k} ${v}`).join(', '));
return out;

// Filters, in the order the brief specifies, each counted so the drop
// breakdown tells you exactly where jobs went:
//   required fields -> description length -> valid date -> age -> role
//   -> location -> dedupe within run -> dedupe against Applications
// Then rank (company boards first, newest first), apply the per-company and
// per-run caps, and shape rows to the Applications header.
//
// Output is ONE item: { rows, stats }. Keeping the rows inside a single item
// (instead of one item per row) means this node always emits something, even
// on a zero-match run, so the If node can route that run straight to the
// Run Log instead of the branch silently stopping.

const cfg = $('Set Job Search Criteria').first().json;
const sheet = $('Index Saved Job Data').first().json;
const all = $input.all().map(i => i.json);
const statuses = all.filter(r => r._kind === 'source_status');
const jobs = all.filter(r => r._kind === 'job');

// ---- matching helpers -------------------------------------------------
// Whole-word match, case-insensitive, optional plural "s". Plain substring
// matching is how 'intern' ends up excluding "internal tools" and 'india'
// ends up blocking "Indianapolis, Indiana".
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordRx = (terms) => terms.length
  ? new RegExp(`(?<![a-z0-9])(?:${terms.map(t => esc(String(t).toLowerCase().trim())).join('|')})s?(?![a-z0-9])`, 'i')
  : null;
const test = (rx, s) => !!rx && rx.test(s);

const roleRx = cfg.filters.map(f => ({ name: f.name, inc: wordRx(f.include ?? []), exc: wordRx(f.exclude ?? []) }));
const matchRole = (j) => {
  const field = cfg.match_in === 'title_and_description' ? `${j.title} ${j.description}` : j.title;
  // Excludes look at the same field as includes. Checking excludes against
  // the description would drop any role that "reports to the Director".
  for (const f of roleRx) if (test(f.inc, field) && !test(f.exc, field)) return f.name;
  return null;
};

const usRx = wordRx(cfg.location_us_explicit);
const blockRx = wordRx(cfg.location_block);
const allowRx = wordRx(cfg.location_allow);
const stateRx = cfg.us_state_codes.length
  ? new RegExp(`,\\s*(?:${cfg.us_state_codes.join('|')})(?![A-Za-z])`)   // case-sensitive on purpose
  : null;
const matchLocation = (loc) => {
  if (!loc) return true;                          // unknown location: let it through
  const segments = loc.split(/\s*(?:;|\||•|\/|\bor\b|\n)\s*/i).filter(Boolean);
  return segments.some(seg =>
    test(usRx, seg) || (!test(blockRx, seg) && (test(allowRx, seg) || test(stateRx, seg))));
};

// ---- URL dedupe key -----------------------------------------------------
// Lowercased host+path with "www." and trailing slashes dropped, fragment
// dropped, and only identity query params kept (cfg.url_id_params).
// Applied identically to new jobs and to links already in Applications.
const idParams = new Set(cfg.url_id_params.map(p => p.toLowerCase()));
const urlKey = (u) => {
  const raw = String(u ?? '').trim();
  try {
    const url = new URL(raw);
    const kept = [...url.searchParams].filter(([k]) => idParams.has(k.toLowerCase()))
      .map(([k, v]) => `${k.toLowerCase()}=${v}`).sort();
    return `${url.hostname.replace(/^www\./, '')}${url.pathname.replace(/\/+$/, '')}${kept.length ? '?' + kept.join('&') : ''}`.toLowerCase();
  } catch {
    return raw.toLowerCase().replace(/#.*$/, '').replace(/\/+$/, '');
  }
};

// ---- filter pass --------------------------------------------------------
const existing = new Set(sheet.existing_links.map(urlKey));
const seen = new Set();
const dayMs = 86400000;
const today = Date.now();
const dropped = { missing_fields: 0, thin_description: 0, bad_date: 0, too_old: 0,
                  no_role_match: 0, location_blocked: 0, duplicate_in_run: 0, already_in_sheet: 0 };
const matched = [];

for (const j of jobs) {
  if (!j.title || !j.url || !j.company) { dropped.missing_fields++; continue; }
  if (j.description.length < cfg.min_desc_len) { dropped.thin_description++; continue; }
  if (!j.posted_date) { dropped.bad_date++; continue; }
  // 0 = no limit. Company boards default to 0: a live ATS listing is an open role.
  const maxAge = j.tier === 'company' ? cfg.max_age_company_days : cfg.max_age_aggregate_days;
  if (maxAge > 0 && (today - Date.parse(j.posted_date + 'T00:00:00Z')) / dayMs > maxAge) { dropped.too_old++; continue; }
  const role = matchRole(j);
  if (!role) { dropped.no_role_match++; continue; }
  if (!matchLocation(j.location)) { dropped.location_blocked++; continue; }
  const key = urlKey(j.url);
  if (seen.has(key)) { dropped.duplicate_in_run++; continue; }
  seen.add(key);
  if (existing.has(key)) { dropped.already_in_sheet++; continue; }
  matched.push({ ...j, matched_filter: role });
}

// ---- rank and cap -------------------------------------------------------
// Company boards first, then newest first; company name as a stable tiebreak.
const tierRank = (j) => (j.tier === 'company' ? 0 : 1);
matched.sort((a, b) => tierRank(a) - tierRank(b) || b.posted_date.localeCompare(a.posted_date) ||
                       a.company.localeCompare(b.company));

// Per-company cap. Jobs over the cap aren't lost: they're not in the sheet,
// so they come back as candidates next run.
const perCompany = {};
let deferredCompanyCap = 0;
const capped = matched.filter(j => {
  const k = j.company.toLowerCase();
  perCompany[k] = (perCompany[k] ?? 0) + 1;
  if (cfg.max_per_company && perCompany[k] > cfg.max_per_company) { deferredCompanyCap++; return false; }
  return true;
});

// Run cap, optionally holding back slots for aggregate boards.
const agg = capped.filter(j => j.tier !== 'company');
const reserve = Math.min(cfg.min_aggregate_slots ?? 0, agg.length, cfg.max_results);
const companyTake = capped.filter(j => j.tier === 'company').slice(0, cfg.max_results - reserve);
const final = [...companyTake, ...agg.slice(0, cfg.max_results - companyTake.length)];
const deferredRunCap = capped.length - final.length;

// ---- shape to the Applications header (exact, lowercase) ----------------------
const trimDesc = (s) => s.length > cfg.desc_max_chars
  ? s.slice(0, cfg.desc_max_chars - 3).replace(/\s+\S*$/, '') + '...'
  : s;
const rows = final.map((j, i) => ({
  's.no': sheet.next_sno + i,
  'company name': j.company,
  'job posting link': j.url,
  'job role': j.title,
  'job description': trimDesc(j.description),
  'day posted': j.posted_date,
  'location': j.location || 'Not stated',
  'matched filter': j.matched_filter,
  'source': j.source,
  'added on': cfg.run_date
}));

const stats = {
  collected: jobs.length,
  matched: matched.length,
  appending: rows.length,
  deferred_company_cap: deferredCompanyCap,
  deferred_run_cap: deferredRunCap,
  dropped,
  existing_row_count: sheet.existing_row_count,
  sources: statuses
};

console.log(`[filter] collected ${jobs.length} | matched ${matched.length} | appending ${rows.length} | ` +
            `deferred: ${deferredCompanyCap} over company cap, ${deferredRunCap} over run cap | ` +
            `dropped ${JSON.stringify(dropped)}`);

return [{ json: { rows, stats } }];

// One row per execution for the 'Run Log' tab: the health check you can read
// without opening n8n. This node is reached by exactly one of two paths:
//   - Append to Applications -> here           (there were new jobs)
//   - Any New Jobs? (false) -> here      (zero new jobs - the run you most
//                                         need logged, because "nothing new"
//                                         and "every board died" look alike)
// 'rows appended' is what the Sheets node actually returned, not what we
// intended to write. Append to Applications continues on error, so a failed append
// is reported here instead of killing the log too.

const cfg = $('Set Job Search Criteria').first().json;
const { rows, stats } = $('Filter and Rank Job Listings').first().json;

let appended = 0;
let appendError = '';
if ($('Append Jobs to Google Sheets').isExecuted) {
  const out = $('Append Jobs to Google Sheets').all().map(i => i.json);
  const err = out.find(r => r && r.error);
  if (err) {
    const e = err.error;
    appendError = typeof e === 'string' ? e : (e?.message ?? 'unknown error');
  } else {
    appended = out.length;
  }
}
const written = appended ? rows.slice(0, appended) : [];

// Count and render "label (n); label (n)" for the top entries.
const tally = (values, limit) => {
  const c = {};
  for (const v of values) c[v] = (c[v] ?? 0) + 1;
  return Object.entries(c).sort((a, b) => b[1] - a[1]).slice(0, limit)
    .map(([k, n]) => `${k} (${n})`).join('; ');
};

const sources = stats.sources.filter(s => s.status !== 'disabled');
const okCount = sources.filter(s => s.status === 'ok').length;
const deadSources = sources.filter(s => s.status !== 'ok').map(s => s.source);
if (appendError) deadSources.push(`Applications append FAILED: ${appendError.slice(0, 120)}`);
const deadBoards = sources.flatMap(s => (s.boards ?? []).filter(b => b.status !== 'ok')
  .map(b => `${b.company} (${s.source}, ${b.reason})`));

const log = {
  'run at': cfg.run_at,
  'sources ok': `${okCount}/${sources.length}`,
  'dead sources': deadSources.join('; ') || 'none',
  'dead company boards': deadBoards.join('; ') || 'none',
  'jobs collected': stats.collected,
  'rows appended': appended,
  'sheet total after run': stats.existing_row_count + appended,
  // First segment only, so "NYC | SF | Remote" counts once, as NYC.
  'top locations': tally(written.map(r => String(r.location).split(/\s*[|;•]\s*/)[0] || 'Not stated'), 8) || 'none',
  'role breakdown': tally(written.map(r => r['matched filter']), 10) || 'none'
};

console.log(`[run log] ${log['sources ok']} sources ok | ${stats.collected} collected | ${appended} appended` +
            (appendError ? ` | APPEND FAILED: ${appendError}` : ''));
return [{ json: log }];
